import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError, GPIOZeroWarning

PWM_FREQUENCY = 1000
PWM_PINS = [1, 2, 3, 4]
POLL_INTERVAL = 0.1

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def apply_pwm(pwm_devices, value):
    for pwm in pwm_devices:
        try:
            pwm.value = value
        except GPIOZeroError as exc:
            print(f"Warning: failed to set PWM on pin {pwm.pin.number}: {exc}", file=sys.stderr)


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    pwm_devices = []
    try:
        for pin in PWM_PINS:
            try:
                pwm = PWMOutputDevice(pin, frequency=PWM_FREQUENCY, initial_value=0)
                pwm_devices.append(pwm)
            except GPIOZeroError as exc:
                print(f"Error: failed to initialize PWM on GPIO {pin}: {exc}", file=sys.stderr)
                for dev in pwm_devices:
                    dev.close()
                sys.exit(1)

        while _running:
            apply_pwm(pwm_devices, 0.5)
            time.sleep(POLL_INTERVAL)
            apply_pwm(pwm_devices, 0)
            time.sleep(POLL_INTERVAL)

    except GPIOZeroError as exc:
        print(f"GPIO error: {exc}", file=sys.stderr)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        for pwm in pwm_devices:
            try:
                pwm.close()
            except Exception:
                pass
        print("PWM devices released.")


if __name__ == "__main__":
    main()

