                print(f"GPIO {PIN} -> ON")
            except (GPIOZeroError, GPIODeviceError) as exc:
                print(f"Warning: failed to write GPIO {PIN}: {exc}", file=sys.stderr)

            for _ in range(int(INTERVAL * 10)):
                if not _running:
                    break
                time.sleep(0.1)

            if not _running:
                break

            try:
                output.off()
                print(f"GPIO {PIN} -> OFF")
            except (GPIOZeroError, GPIODeviceError) as exc:
                print(f"Warning: failed to write GPIO {PIN}: {exc}", file=sys.stderr)

            for _ in range(int(INTERVAL * 10)):
                if not _running:
                    break
                time.sleep(0.1)

    finally:
        try:
            output.close()
        except Exception:
            pass
        print("GPIO cleanup done.")


