import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

# BCM pin numbers for the digital outputs
OUTPUT_PINS = (17, 27)

# Global list so the signal handler can close them
_devices = []
_running = True


def _cleanup():
    """Close every OutputDevice we opened."""
    for dev in _devices:
        try:
            dev.close()
        except DeviceClosed:
            pass
        except Exception:
            pass


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def _validate_reading(reading):
    """Return True if the reading is a valid integer (0 or 1)."""
    return isinstance(reading, int) and 0 <= reading <= 1


def main():
    global _devices

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialize OutputDevice objects; gpiozero raises GPIOZeroError on failure
    for pin in OUTPUT_PINS:
        try:
            dev = OutputDevice(pin)
            _devices.append(dev)
        except GPIOZeroError as exc:
            print(f"Error: failed to initialize GPIO {pin}: {exc}", file=sys.stderr)
            _cleanup()
            sys.exit(1)
        except Exception as exc:
            print(f"Error: unexpected failure on GPIO {pin}: {exc}", file=sys.stderr)
            _cleanup()
            sys.exit(1)

    print(f"Monitoring GPIO {OUTPUT_PINS} every 60 seconds. Press Ctrl+C to stop.")

    try:
        while _running:
            for pin in OUTPUT_PINS:
                try:
                    dev = _devices[pin]
                except IndexError:
                    continue

                try:
                    reading = dev.value
                except DeviceClosed:
                    print(f"Warning: device closed on GPIO {pin}; skipping.", file=sys.stderr)
                    continue
                except GPIOZeroError as exc:
                    print(f"Warning: read error on GPIO {pin}: {exc}", file=sys.stderr)
                    continue

                if not _validate_reading(reading):
                    print(f"Warning: invalid reading on GPIO {pin}: {reading!r}", file=sys.stderr)
                    continue

                print(f"GPIO {pin} -> {reading}")

            # Sleep in small increments so signals are caught promptly
            slept = 0
            while _running and slept < 60:
                time.sleep(1)
                slept += 1

    finally:
        _cleanup()
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

import signal
import sys
import smbus2

MPU6050_ADDR = 0x68
I2C_BUS = 1

running = True

def handle_signal(signum, frame):
    global running
    running = False

def read_raw_data(bus, addr):
    try:
        data = bus.read_i2c_block_data(addr, 0x3B, 6)
        return (data[0] << 8) | data[1], (data[2] << 8) | data[3], (data[4] << 8) | data[5]
    except OSError as e:
        print(f"I2C read error at 0x{addr:02X}: {e}", file=sys.stderr)
        return None, None, None

def main():
    global running
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        bus = smbus2.SMBus(I2C_BUS)
    except OSError as e:
        print(f"Cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            ax, ay, az = read_raw_data(bus, MPU6050_ADDR)
            if ax is not None:
                print(f"Accel X: {ax}, Accel Y: {ay}, Accel Z: {az}")
            else:
                print("Failed to read accelerometer data.", file=sys.stderr)
                break
    finally:
        bus.close()
        print("I2C bus closed.")

if __name__ == "__main__":
    main()

