import serial
import time
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
TIMEOUT = 1
READ_INTERVAL = 1.0

# Expected device response: a single byte (0x00-0xFF)
EXPECTED_RESPONSE = 0x00

def read_sensor_data(serial_connection):
    """Read a single byte from the serial port and return it, or None on error."""
    try:
        raw = serial_connection.read(1)
        if not raw:
            return None
        return raw[0]
    except serial.SerialException as e:
        print(f"Serial communication error: {e}", file=sys.stderr)
        return None
    except OSError as e:
        print(f"OS error reading from serial port: {e}", file=sys.stderr)
        return None

def validate_sensor_data(sensor_value):
    """Return True if the sensor value is within the documented range."""
    return 0 <= sensor_value <= 0xFF

def main():
    serial_connection = None
    try:
        serial_connection = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=TIMEOUT
        )
        print(f"Connected to {SERIAL_PORT} at {BAUD_RATE} baud.")

        while True:
            sensor_value = read_sensor_data(serial_connection)
            if sensor_value is not None:
                if validate_sensor_data(sensor_value):
                    print(f"Sensor Value: {sensor_value}")
                else:
                    print(f"Invalid sensor value: {sensor_value}", file=sys.stderr)
            time.sleep(READ_INTERVAL)

    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        if serial_connection is not None and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

