import signal
import sys
import time

import board
import busio
import adafruit_mcp3xxx.mcp3008 as MCP

NUM_READINGS = 25
SAMPLE_DELAY = 0.05  # seconds between readings

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_mcp3008_channel(channel: int) -> int | None:
    """Read a single-ended channel from the MCP3008.

    Returns the 10-bit value (0-1023) or None on failure.
    """
    try:
        return mcp.read_adc(channel)
    except OSError as exc:
        print(f"[ERROR] Failed to read MCP3008 channel {channel}: {exc}", file=sys.stderr)
        return None


def main() -> int:
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # --- Initialize MCP3008 -------------------------------------------------
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"[ERROR] Failed to initialize I2C bus: {exc}", file=sys.stderr)
        return 1

    try:
        mcp = MCP.MCP3008(i2c)
    except Exception as exc:
        print(f"[ERROR] Failed to initialize MCP3008: {exc}", file=sys.stderr)
        return 1

    print("Starting MCP3008 channel sampling (25 readings, 0.05 s interval)...")
    print("Press Ctrl+C to stop early.\n")

    # --- Sampling loop ------------------------------------------------------
    try:
        for i in range(NUM_READINGS):
            if not _running:
                break

            value = read_mcp3008_channel(0)
            if value is not None:
                print(f"Reading {i + 1}/{NUM_READINGS}: Channel 0 -> {value}")
            else:
                print(f"Reading {i + 1}/{NUM_READINGS}: Channel 0 -> ERROR")

            if i < NUM_READINGS - 1 and _running:
                time.sleep(SAMPLE_DELAY)

    except Exception as exc:
        print(f"[ERROR] Unexpected error during sampling: {exc}", file=sys.stderr)
        return 1

    finally:
        try:
            mcp.deinit()
        except Exception:
            pass
        print("\nMCP3008 hardware released. Exiting.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

