import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

BME680_I2C_ADDR = 0x77
BME680_REG_ID = 0xD0
BME680_ID_EXPECTED = 0x60

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _read_register(bus, reg):
    write_msg = i2c_msg.write(BME680_I2C_ADDR, [reg])
    read_msg = i2c_msg.read(BME680_I2C_ADDR, 1)
    bus.i2c_rdwr(write_msg, read_msg)
    return list(read_msg)


def _read_measurement(bus):
    data = _read_register(bus, 0xF7)
    if len(data) < 8:
        raise IOError(f"Short read: got {len(data)} bytes, expected 8")
    raw = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)
    return raw


def _validate_measurement(raw):
    if raw & 0x10000000:
        raise IOError("Measurement is invalid (status bit set)")
    if raw & 0x08000000:
        raise IOError("Measurement is not ready (status bit set)")
    return True


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(1)
    except OSError as exc:
        print(f"Error: cannot open I2C bus 1: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        # Probe the device ID register.
        try:
            device_id = _read_register(bus, BME680_REG_ID)[0]
        except OSError as exc:
            print(f"Error: no BME680 found at 0x{BME680_I2C_ADDR:02X}: {exc}", file=sys.stderr)
            bus.close()
            sys.exit(1)

        if device_id != BME680_ID_EXPECTED:
            print(
                f"Error: unexpected device ID 0x{device_id:02X} "
                f"(expected 0x{BME680_ID_EXPECTED:02X})",
                file=sys.stderr,
            )
            bus.close()
            sys.exit(1)

        print("BME680 initialized. Reading once every 1 second. Press Ctrl+C to stop.")

        while _running:
            try:
                raw = _read_measurement(bus)
                if not _validate_measurement(raw):
                    raise IOError("Measurement is not valid")
                print(f"Temperature: {raw / 100.0:.2f} °C")
            except IOError as exc:
                print(f"Error reading BME680: {exc}", file=sys.stderr)
            except OSError as exc:
                print(f"I2C bus error: {exc}", file=sys.stderr)

            # Sleep in small increments so signals are caught promptly.
            slept = 0.0
            while _running and slept < 1.0:
                time.sleep(0.1)
                slept += 0.1

    finally:
        bus.close()
        print("I2C bus closed. Exiting.")


if __name__ == "__main__":
    main()

