import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, GPIODeviceError

# BCM pin numbers for the digital outputs
OUTPUT_PINS = [4, 17, 18, 22, 23, 24, 25, 27]

# Global list of OutputDevice instances for cleanup
_devices = []
_running = True


def _cleanup():
    """Release all GPIO resources."""
    for dev in _devices:
        try:
            dev.close()
        except Exception:
            pass
    _devices.clear()


def _handle_signal(signum, frame):
    """Signal handler for graceful shutdown."""
    global _running
    _running = False


def _validate_reading(reading):
    """Return True if the reading is a valid integer (0-255) or None."""
    if reading is None:
        return None
    try:
        value = int(reading)
    except (TypeError, ValueError):
        return None
    if not (0 <= value <= 255):
        return None
    return value


def main():
    global _devices

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        # Initialize OutputDevice objects for each pin
        for pin in OUTPUT_PINS:
            try:
                dev = OutputDevice(pin)
                _devices.append(dev)
            except (GPIOZeroError, GPIODeviceError) as exc:
                print(f"Error: failed to initialize GPIO {pin}: {exc}", file=sys.stderr)
                _cleanup()
                sys.exit(1)

        print("GPIO output control started. Press Ctrl+C to stop.")

        while _running:
            try:
                # Read the digital output from each pin
                readings = []
                for pin in OUTPUT_PINS:
                    try:
                        value = _devices[pin].value
                    except (GPIOZeroError, GPIODeviceError) as exc:
                        print(f"Warning: failed to read GPIO {pin}: {exc}", file=sys.stderr)
                        value = None
                    readings.append(value)

                # Validate each reading
                valid_readings = []
                for i, reading in enumerate(readings):
                    if reading is not None:
                        valid_readings.append(reading)

                # Apply the valid readings to standard output
                if valid_readings:
                    print("GPIO Output:", end=" ")
                    for i, reading in enumerate(valid_readings):
                        print(f"GPIO{OUTPUT_PINS[i]}={reading}", end=" ")
                    print()

            except Exception as exc:
                print(f"Unexpected error in main loop: {exc}", file=sys.stderr)

            # Wait 0.001 seconds before the next reading
            time.sleep(0.001)

    except Exception as exc:
        print(f"Fatal error: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)
    finally:
        _cleanup()
        print("GPIO cleanup complete.")


if __name__ == "__main__":
    main()

