import signal
import sys
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

# BCM pin number for the digital output
OUTPUT_PIN = 17

# Global reference for signal handler cleanup
_output = None

def cleanup(signum=None, frame=None):
    """Release GPIO resources and exit cleanly."""
    global _output
    if _output is not None:
        try:
            _output.close()
        except Exception:
            pass
        _output = None
    if signum is not None:
        sys.exit(0)

def main():
    global _output

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        # Initialize the digital output device
        _output = OutputDevice(OUTPUT_PIN)
    except GPIOZeroError as e:
        print(f"Failed to initialize GPIO {OUTPUT_PIN}: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error initializing GPIO {OUTPUT_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        # Drive the output HIGH for 5 cycles
        for i in range(5):
            _output.on()
            print(f"Cycle {i + 1}: GPIO {OUTPUT_PIN} -> HIGH")
            # Sleep in small increments to allow signal handling
            for _ in range(10):
                if _output is None:
                    break
                signal.pause()

        # Drive the output LOW for 5 cycles
        for i in range(5):
            _output.off()
            print(f"Cycle {i + 1}: GPIO {OUTPUT_PIN} -> LOW")
            for _ in range(10):
                if _output is None:
                    break
                signal.pause()

    except Exception as e:
        print(f"Runtime error during GPIO operation: {e}", file=sys.stderr)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

