import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
PCA9685_ADDRESS = 0x40

running = True
bus = None


def handle_signal(signum, frame):
    global running
    running = False


def read_measurement(bus):
    """Read a single measurement from the PCA9685 and return the value."""
    write_msg = i2c_msg.write(PCA9685_ADDRESS, [0x00])
    bus.i2c_rdwr(write_msg)
    read_msg = i2c_msg.read(PCA9685_ADDRESS, 2)
    bus.i2c_rdwr(read_msg)
    return (read_msg.buf[0] << 8) | read_msg.buf[1]


def main():
    global bus

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            try:
                value = read_measurement(bus)
                print(value)
            except OSError as exc:
                print(f"Warning: I2C read error: {exc}", file=sys.stderr)

            time.sleep(0.005)
    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass


if __name__ == "__main__":
    main()

