import serial
import time
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
READ_INTERVAL = 0.1

def main():
    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
        print(f"Connected to {SERIAL_PORT} @ {BAUD_RATE} baud.")
        while True:
            try:
                raw = ser.readline()
                if not raw:
                    print("Warning: no data received (timeout).")
                    continue
                line = raw.decode('ascii', errors='replace').strip()
                if line:
                    print(f"Received: {line}")
            except serial.SerialException as e:
                print(f"Serial communication error: {e}")
                break
            time.sleep(READ_INTERVAL)
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}")
        sys.exit(1)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

import serial
import time
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
READ_INTERVAL = 2.0
NUM_READINGS = 3

running = True

def handle_signal(signum, frame):
    global running
    running = False

def main():
    global running

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1.0)
        print(f"Connected to {SERIAL_PORT} @ {BAUD_RATE} baud.")

        for i in range(NUM_READINGS):
            if not running:
                break

            try:
                raw = ser.readline()
                if not raw:
                    print(f"Reading {i+1}/{NUM_READINGS}: No data received (timeout).")
                else:
                    line = raw.decode('ascii', errors='replace').strip()
                    if line:
                        print(f"Reading {i+1}/{NUM_READINGS}: {line}")
            except serial.SerialException as e:
                print(f"Error reading from serial port: {e}")
                break
            except OSError as e:
                print(f"I/O error during serial read: {e}")
                break

            if i < NUM_READINGS - 1 and running:
                time.sleep(READ_INTERVAL)

    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}")
        sys.exit(1)
    except OSError as e:
        print(f"OS error opening serial port {SERIAL_PORT}: {e}")
        sys.exit(1)
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

