    main()

import time
import signal
import sys
import board
import busio
import adafruit_mcp3xxx.mcp3008 as MCP

# --- Configuration -----------------------------------------------------------
ADC_CHANNEL = 0          # MCP3008 single-ended channel 0
SAMPLE_INTERVAL = 5.0    # seconds between readings
MAX_RETRIES = 3         # retry attempts on transient read failures
RETRY_DELAY = 0.1        # seconds between retry attempts

# --- Globals for cleanup -----------------------------------------------------
_running = True
_adc = None


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def _cleanup():
    """Release hardware resources."""
    global _adc
    if _adc is not None:
        try:
            _adc.deinit()
        except Exception:
            pass
        _adc = None


def read_adc_channel(adc, channel):
    """
    Read a single-ended channel from the MCP3008.

    Returns the raw 10-bit value (0-1023) or None on failure.
    """
    if not 0 <= channel <= 7:
        raise ValueError(f"Invalid MCP3008 channel {channel}; must be 0-7.")

    for attempt in range(1, MAX_RETRIES + 1):
        try:
            value = adc.read_adc(channel)
        except Exception as exc:
            print(f"[WARN] Read attempt {attempt}/{MAX_RETRIES} failed: {exc}",
                  file=sys.stderr)
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
            else:
                return None

        if value is None:
            print(f"[WARN] Read attempt {attempt}/{MAX_RETRIES} returned None.",
                  file=sys.stderr)
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
            else:
                return None

        # CircuitPython MCP3008 returns a 10-bit value (0-1023).
        if not 0 <= value <= 1023:
            print(f"[WARN] Read attempt {attempt}/{MAX_RETRIES} "
                  f"out-of-range: {value}", file=sys.stderr)
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
            else:
                return None

        return value


def main():
    global _adc

    # Register signal handlers for clean shutdown.
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # --- Initialise the MCP3008 ADC -----------------------------------------
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"[ERROR] Failed to initialise I2C bus: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        _adc = MCP.MCP3008(i2c, address=0x70)
    except Exception as exc:
        print(f"[ERROR] MCP3008 not found at I2C address 0x70: {exc}",
              file=sys.stderr)
        _cleanup()
        sys.exit(1)

    print(f"MCP3008 initialised on I2C bus, channel {ADC_CHANNEL}.")

    # --- Main sampling loop ----------------------------------------------------
    try:
        while _running:
            raw = read_adc_channel(_adc, ADC_CHANNEL)
            if raw is not None:
                print(f"ADC Channel {ADC_CHANNEL}: {raw}")
            else:
                print(f"ADC Channel {ADC_CHANNEL}: read failed after "
                      f"{MAX_RETRIES} attempts.", file=sys.stderr)

            # Sleep in small increments so signals are caught promptly.
            slept = 0.0
            while _running and slept < SAMPLE_INTERVAL:
                time.sleep(0.1)
                slept += 0.1

    except Exception as exc:
        print(f"[ERROR] Unexpected error in main loop: {exc}", file=sys.stderr)
    finally:
        _cleanup()
        print("Program terminated cleanly.")


if __name__ == "__main__":
    main()
